<script setup lang="ts">
import {computed} from 'vue';
import type {Page} from './model';
import FolderIcon from './FolderIcon.vue';
import MenuDetailLinks from './MenuDetailLinks.vue';
const props=defineProps<{node:Page;pages:Page[];openIds:string[];details?:Page[];source?:string}>(),emit=defineEmits<{select:[id:string];settings:[id:string];toggle:[id:string];detail:[id:string]}>();
const children=computed(()=>props.pages.filter(p=>p.parent===props.node.id));
</script>
<template><details v-if="children.length" class="map-menu" :open="openIds.includes(node.id)"><summary @click.prevent="emit('toggle',node.id)"><span class="map-menu-title"><button type="button" class="map-page-link" @click.stop.prevent="emit('select',node.id)"><FolderIcon/><strong>{{node.title}}</strong></button><button class="map-node-settings" :aria-label="'栏目设置 '+node.title" @click.stop.prevent="emit('settings',node.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 4 6 6M3 21l2-7L16 3a2.8 2.8 0 0 1 4 4L9 18Z"/></svg></button></span></summary><MenuDetailLinks v-if="details&&source" :menu-id="node.id" :pages="details" :source="source" @edit="emit('detail',$event)"/><div class="map-dropdown"><ul><li v-for="child in children" :key="child.id"><WebsiteTreeNode :node="child" :pages="pages" :open-ids="openIds" :details="details" :source="source" @detail="emit('detail',$event)" @select="emit('select',$event)" @settings="emit('settings',$event)" @toggle="emit('toggle',$event)"/></li></ul></div></details><span v-else class="map-leaf-row"><button class="map-overview-node" @click="emit('select',node.id)"><FolderIcon/><strong>{{node.title}}</strong></button><button class="map-node-settings" :aria-label="'栏目设置 '+node.title" @click="emit('settings',node.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 4 6 6M3 21l2-7L16 3a2.8 2.8 0 0 1 4 4L9 18Z"/></svg></button></span><MenuDetailLinks v-if="!children.length&&details&&source" :menu-id="node.id" :pages="details" :source="source" @edit="emit('detail',$event)"/></template>
